import numpy as np, os,re,json
from scipy import ndimage
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(a):
    a=np.array(a); vals,cnt=np.unique(a,return_counts=True)
    bg=vals[np.argmax(cnt)]
    out=a.copy(); lab,n=ndimage.label(a!=bg)
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        for col in np.unique(a[ys,xs]):
            mk=(a==col)&(lab==i)
            ys2,xs2=np.where(mk)
            r0,r1,c0,c1=ys2.min(),ys2.max(),xs2.min(),xs2.max()
            sub=a[r0:r1+1,c0:c1+1]; h,w=sub.shape
            corners={(0,0),(0,w-1),(h-1,0),(h-1,w-1)}
            new=sub.copy()
            for r in range(h):
                for c in range(w):
                    if (r,c) in corners: new[r,c]=1
                    elif r in (0,h-1) or c in (0,w-1): new[r,c]=4
                    else: new[r,c]=2
            out[r0:r1+1,c0:c1+1]=new
    return out.tolist()
